extern void debug_print(const char *, ...);

#define MAXTOKEN 65
#define assert(x) ((void)0)

class text_parser
{
public:
  bool get_token (bool crossline, bool optional);

  char token[65];
private:
  char *buffer;
  char *script_ptr;
  char last_val;
  char padding[3];
  char *last_val_pos;
  int script_line;
};

bool text_parser::get_token (bool crossline, bool optional)
{
  char *token_p;

skipspace:
  while (*script_ptr <= 32)
  {
    // EOF 
    if (*script_ptr == 26)
    {
      if (!crossline && !optional)
      {
      	debug_print ("text_parser: Script line %i is incomplete\n", script_line);
        assert (false);
      }
      return false;

    }
    if (!*script_ptr)
    {
      if (!crossline && !optional)
      {
      	debug_print ("text_parser: Script line %i is incomplete\n", script_line);
        assert (false);
      }
      return false;
    }

    if (*script_ptr++ == '\n')
    {
      if (!crossline)
      {
        if (optional)
          return false;
        else
        {
          debug_print ("text_parser: Script line %i is incomplete\n", script_line);
          assert (false);
        }
      }
      script_line++;
    }
  }

  // comment field
  if (script_ptr[0] == '/' && script_ptr[1] == '/')
  {
    if (!crossline && !optional)
    {
      if (optional)
        return false;
      else
      {
        debug_print ("text_parser: Script line %i is incomplete\n", script_line);
        assert (false);
      }
    }

    while ((*script_ptr != '\n') && ( *script_ptr != 0x26 )) 
      if (!*(++script_ptr))
      {
        if (!crossline && !optional)
        {
          debug_print ("text_parser: Script line %i is incomplete\n", script_line);
          assert (false);
        }
        return false;
      }
      goto skipspace;
  }

  // copy token
  token_p = token;

  if (*script_ptr == '"')
  {
    script_ptr++;
    while (*script_ptr != '"')
    {
      if (!*script_ptr)
      {
        debug_print ("text_parser: EOF inside quoted token\n");
        assert (false);
      }
      *token_p++ = *script_ptr++;
      if (token_p == &token[MAXTOKEN])
      {
        debug_print ("text_parser: Token too large on line %i\n",script_line);
        assert (false);
      }
    }
    script_ptr++;
  }
  else while (*script_ptr > 32)
  {
    *token_p++ = *script_ptr++;
    if (token_p == &token[MAXTOKEN])
    {
      debug_print ("text_parser: Token too large on line %i\n",script_line);
      assert (false);
    }
  }

  *token_p = 0;

  return true;
}
